let data=[],optimization=null;const $=id=>document.getElementById(id),n=(r,k)=>Number(r[k]||0),pct=x=>`${(100*Number(x||0)).toFixed(0)}%`,band=x=>x>.7?'High':x>.4?'Medium':'Low',esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),badge=(x,c=x)=>`<span class="badge ${esc(String(c).toLowerCase().replace(/[^a-z0-9_-]/g,''))}">${esc(x)}</span>`;
function csv(t){const a=[],r=[];let row=[],cell='',q=false;for(let i=0;i<t.length;i++){const c=t[i],z=t[i+1];if(c==='"'&&q&&z==='"'){cell+='"';i++}else if(c==='"')q=!q;else if(c===','&&!q){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!q){if(c==='\r'&&z==='\n')i++;row.push(cell);if(row.some(Boolean))a.push(row);row=[];cell=''}else cell+=c}if(cell||row.length){row.push(cell);a.push(row)}const[h,...b]=a;return b.map(v=>Object.fromEntries(h.map((k,i)=>[k.trim(),(v[i]||'').trim()])))}
function points(r){const v=r.story_points??r.effort_estimate,p=Number(v);return v===undefined||v===null||v===''||!Number.isFinite(p)||p<0?null:p}function primary(r){return[['volatility_risk','Requirement volatility'],['resolution_risk','Resolution delay'],['reopen_risk','Reopen']].sort((a,b)=>n(r,b[0])-n(r,a[0]))[0]}function actionReason(r){return r.action_reason||`${r.planner_action} with ${r.risk_band} combined risk; strongest score is ${primary(r)[1]}.`}function ruleWork(){return data.reduce((s,r)=>s+((r.planner_action==='Include'||r.planner_action==='Monitor')?(points(r)||0):r.planner_action==='Split'?(points(r)||0)*.5:0),0)}
function explanationHtml(r){let e=r.explanations;if(typeof e==='string'){try{e=JSON.parse(e)}catch{e=null}}if(!e||typeof e!=='object')return'<p class="detail">No model-derived explanation is available for this uploaded register.</p>';return[['volatility_risk','Requirement volatility'],['resolution_risk','Resolution delay'],['reopen_risk','Reopen']].map(([k,l])=>{const x=e[k];if(!x)return`<h4>${l}</h4><p>Explanation unavailable.</p>`;const f=(x.factors||[]).map(v=>`<div class="factor">${esc(v.label)}: ${esc(v.direction)} score (${Number(v.contribution).toFixed(4)})</div>`).join('');return`<h4>${l}</h4><p class="detail">${esc(x.method)}</p>${f||'<p>No non-zero contributions.</p>'}${x.limitation?`<p class="detail">${esc(x.limitation)}</p>`:''}`}).join('')+'<p class="detail">Contributions are associations relative to a reference, not causal proof.</p>'}
function optimizerView(){const c=$('optimizerCard');if(!optimization){c.hidden=true;return}c.hidden=false;$('optimizerSummary').textContent=`${optimization.method}: commits ${optimization.committed_effort}/${optimization.capacity} story points, leaving ${optimization.remaining_capacity}.`;$('optimizerItems').innerHTML=optimization.selected_issue_keys.map(k=>badge(`Commit ${k}`,'include')).join('')}
function overview(){const cap=n({v:$('capacityInput').value},'v'),work=optimization?optimization.committed_effort:ruleWork(),high=data.filter(r=>n(r,'combined_risk')>.7).length,mean=data.reduce((s,r)=>s+n(r,'combined_risk'),0)/data.length,score=Math.round(100*(1-(.7*mean+.3*high/data.length))*10)/10;$('recommendedWork').textContent=work.toFixed(1);$('commitmentDetail').textContent=optimization?`Optimised portfolio is ${work<=cap?'within':'over'} the ${cap}-point capacity by ${Math.abs(cap-work).toFixed(1)} points.`:`${work<=cap?'Within':'Over'} the ${cap}-point capacity by ${Math.abs(cap-work).toFixed(1)} points.`;$('healthScore').textContent=score;$('healthBand').textContent=score>=70?'Healthy':score>=45?'At Risk':'Critical';$('healthBar').style.width=`${score}%`;$('highRisk').textContent=high;$('actionDistribution').innerHTML=['Include','Monitor','Split','Defer'].map(a=>`<div class="action-box ${a.toLowerCase()}"><span>${a}</span><strong>${data.filter(r=>r.planner_action===a).length}</strong></div>`).join('');optimizerView()}
function drill(r){const rec=r.llm_recommendation,label=rec?'Regenerate mitigation':'Generate mitigation',portfolio=r.optimizer_decision?`<section><h3>Portfolio optimisation</h3><p>${badge(r.optimizer_decision,r.optimizer_decision==='Commit'?'include':'defer')} — ${esc(r.optimizer_reason)}</p></section>`:'';const mitigation=rec?`<h4>Approved mitigation strategies</h4><ul>${rec.approved_recommendations.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h4>Issue-specific LLM guidance</h4><p>${esc(rec.tailored_guidance||'No tailored guidance was generated.')}</p><p class="detail">${esc(rec.tailored_guidance_status||'Generated guidance; review before acting.')}</p><h4>Why this mitigation</h4><p>${esc(rec.contextual_rationale||rec.rationale)}</p><p class="${rec.fallback_used?'fallback':'grounded'}">${rec.fallback_used?'Fallback approved strategy used':'Approved strategy IDs validated'}</p>`:'<p class="detail">Generate grounded, issue-specific mitigation guidance for this item.</p>';$('detailContent').innerHTML=`<h2>${esc(r.issue_key)}</h2><p class="detail">${esc(r.summary||r.summary_at_cutoff||'No issue summary was included.')}</p><section><h3>Recommended action</h3><p>${esc(r.planner_action)} — ${esc(actionReason(r))}</p></section>${portfolio}<section><h3>Per-issue explanations</h3>${explanationHtml(r)}</section><section><h3>LLM mitigation recommendation</h3>${mitigation}<button id="generateOne">${label}</button></section>`;$('detailPanel').classList.add('open');$('generateOne').onclick=async()=>{const b=$('generateOne');b.disabled=true;b.textContent='Generating…';try{r.llm_recommendation=(await post('/api/llm-recommendations',{items:[r]})).items[0].llm_recommendation;drill(r)}catch(e){error(e.message);b.disabled=false;b.textContent=label}}}
function render(){if(!data.length)return;overview();const shown=data.filter(r=>($('bandFilter').value==='All'||r.risk_band===$('bandFilter').value)&&($('actionFilter').value==='All'||r.planner_action===$('actionFilter').value));const sort=$('sortBy').value;shown.sort((a,b)=>sort==='points'?(points(b)||-1)-(points(a)||-1):sort==='action'?a.planner_action.localeCompare(b.planner_action):n(b,'combined_risk')-n(a,'combined_risk'));$('rows').innerHTML=shown.length?shown.map(r=>{const dep=String(r.has_dependencies??'').toLowerCase(),depLabel=['1','true','yes','y'].includes(dep)?'Yes':['0','false','no','n'].includes(dep)?'No':'Unknown';return`<tr data-index="${data.indexOf(r)}"><td><strong>${esc(r.issue_key)}</strong><div class="summary">${esc(r.summary||r.summary_at_cutoff||'No summary provided')}</div></td><td>${points(r)??'—'}</td><td>${pct(n(r,'volatility_risk'))}<br>${badge(band(n(r,'volatility_risk')))}</td><td>${pct(n(r,'resolution_risk'))}<br>${badge(band(n(r,'resolution_risk')))}</td><td>${pct(n(r,'reopen_risk'))}<br>${badge(band(n(r,'reopen_risk')))}</td><td>${badge(r.priority||r.priority_at_cutoff||'—')}</td><td>${depLabel}</td><td>${badge(r.planner_action)}${r.optimizer_decision?`<div class="detail">${esc(r.optimizer_decision)}</div>`:''}</td></tr>`}).join(''):'<tr><td colspan="8" class="empty">No items match these filters.</td></tr>';document.querySelectorAll('tr[data-index]').forEach(x=>x.onclick=()=>drill(data[x.dataset.index]))}
function error(x){$('notice').textContent=x;$('notice').className='notice show'}async function post(u,b){const r=await fetch(u,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b)}),o=await r.json();if(!r.ok)throw Error(o.error||'Request failed.');return o}async function load(items,name){if(!items.length)throw Error('CSV is empty.');const candidate=!('combined_risk'in items[0]);$('sourceStatus').textContent=candidate?'Scoring candidates…':'Loading risk register…';const o=await post(candidate?'/api/score-candidates':'/api/sprint-summary',{items});data=o.items;optimization=null;$('sourceStatus').textContent=`${name}${candidate?' — model-scored candidates':' — uploaded register'}`;$('notice').className='notice';$('generateRecommendations').disabled=false;$('optimizeSprint').disabled=false;render()}async function generate(){const b=$('generateRecommendations');b.disabled=true;b.textContent='Generating…';try{data=(await post('/api/llm-recommendations',{items:data})).items;render()}catch(e){error(e.message)}finally{b.disabled=false;b.textContent='Generate LLM recommendations'}}async function optimise(){const b=$('optimizeSprint');b.disabled=true;b.textContent='Optimising…';try{const o=await post('/api/optimize-sprint',{items:data,capacity:Number($('capacityInput').value)});data=o.items;optimization=o.optimization;render()}catch(e){error(e.message)}finally{b.disabled=false;b.textContent='Optimise sprint composition'}}
$('fileInput').onchange=e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>load(csv(r.result),f.name).catch(x=>error(x.message));r.readAsText(f)};$('generateRecommendations').onclick=generate;$('optimizeSprint').onclick=optimise;$('capacityInput').oninput=()=>{optimization=null;render()};['bandFilter','actionFilter','sortBy'].forEach(x=>$(x).onchange=render);$('closePanel').onclick=()=>$('detailPanel').classList.remove('open');
